\begin{matrix}
\text{category of groupoid schemes} \\
\text{cartesian over } (X, X \times_Y X, \ldots)
\end{matrix}
\longrightarrow
\begin{matrix}
\text{ category of descent data} \\
\text{ relative to } X/Y
\end{matrix}
$$

